/**
 * Review "mnemonic scene": one cached line of imagery per word, generated by
 * the active provider on first reveal. Failures are cheap — the scene is a
 * bonus, never a gate on reviewing.
 */

import { getLearning } from "../shared/learning-storage";
import { buildMnemonicPrompt, sanitizeCaption } from "../shared/mnemonic";
import { getSettings } from "../shared/storage";
import type {
  CompletionRequest,
  CompletionResult,
} from "../providers/types";
import { complete } from "../providers/openai";
import type {
  LearningState,
  MnemonicResponse,
  ProviderConfig,
  Settings,
  WordMnemonic,
} from "../shared/types";
import { runLearningUpdate } from "./storage-queue";

export interface MnemonicDeps {
  getLearning(): Promise<LearningState>;
  getSettings(): Promise<Settings>;
  complete(cfg: ProviderConfig, req: CompletionRequest): Promise<CompletionResult>;
  save(id: string, mnemonic: WordMnemonic): Promise<void>;
  now(): number;
}

/** Real deps; tests inject their own so nothing touches chrome.storage. */
export function createMnemonicDeps(overrides: Partial<MnemonicDeps> = {}): MnemonicDeps {
  return {
    getLearning,
    getSettings,
    complete,
    save: async (id, mnemonic) => {
      await runLearningUpdate((state) => {
        const word = state.words.find((entry) => entry.id === id);
        if (word) word.mnemonic = mnemonic;
        return { state, result: undefined };
      });
    },
    now: () => Date.now(),
    ...overrides,
  };
}

function activeProvider(settings: Settings): ProviderConfig | undefined {
  const chosen =
    settings.providers.find((provider) => provider.id === settings.activeProviderId) ??
    settings.providers[0];
  if (!chosen || !chosen.apiKey || !chosen.model) return undefined;
  return chosen;
}

export async function generateMnemonic(
  id: string,
  deps: MnemonicDeps,
): Promise<MnemonicResponse> {
  const state = await deps.getLearning();
  const word = state.words.find((entry) => entry.id === id);
  if (!word) return { ok: false, reason: "unknown-word" };
  if (word.mnemonic) return { ok: true, mnemonic: word.mnemonic };

  const settings = await deps.getSettings();
  const provider = activeProvider(settings);
  if (!provider) return { ok: false, reason: "no-provider" };

  const primary =
    word.glosses.find((gloss) => gloss.lang === word.glossLang) ?? word.glosses[0];
  const lang = word.glossLang || settings.targetLang || "zh-CN";

  let caption = "";
  try {
    const result = await deps.complete(provider, {
      messages: buildMnemonicPrompt({
        surface: word.surface,
        termLang: word.termLang,
        pos: word.pos,
        meaning: primary?.meaning ?? "",
        sentence: word.contexts[0]?.sentence ?? "",
        lang,
      }),
      temperature: 0.8,
      maxTokens: 120,
    });
    caption = sanitizeCaption(result.text);
  } catch {
    return { ok: false, reason: "failed" };
  }
  if (!caption) return { ok: false, reason: "failed" };

  const mnemonic: WordMnemonic = { caption, lang, at: deps.now() };
  await deps.save(id, mnemonic);
  return { ok: true, mnemonic };
}
